def backfill_settlement_sources(apps, _schema_editor):
    Settlement = apps.get_model("after_sales_api", "Settlement")
    ProjectNode = apps.get_model("after_sales_api", "ProjectNode")
    ProjectAssignment = apps.get_model("after_sales_api", "ProjectAssignment")
    used_node_ids = set()
    used_assignment_ids = set()
    for settlement in Settlement.objects.select_related("project").order_by("created_at", "id"):
        nodes = list(ProjectNode.objects.filter(project_id=settlement.project_id).order_by("sequence", "id"))
        if not nodes:
            continue
        preferred = next(
            (node for node in nodes if node.node_key == settlement.project.current_node_key),
            None,
        )
        ordered = ([preferred] if preferred else []) + [node for node in nodes if node != preferred]
        if settlement.status != "cancelled":
            node = next((item for item in ordered if item.id not in used_node_ids), None)
        else:
            node = ordered[0]
        if node is None:
            continue
        assignment = ProjectAssignment.objects.filter(node_id=node.id).order_by("id").first()
        if (
            assignment is not None
            and settlement.status != "cancelled"
            and assignment.id in used_assignment_ids
        ):
            assignment = None
        settlement.source_node_id = node.id
        settlement.source_assignment_id = assignment.id if assignment else None
        settlement.save(update_fields=["source_node", "source_assignment"])
        if settlement.status != "cancelled":
            used_node_ids.add(node.id)
            if assignment:
                used_assignment_ids.add(assignment.id)


def clear_settlement_sources(apps, _schema_editor):
    Settlement = apps.get_model("after_sales_api", "Settlement")
    Settlement.objects.update(source_node=None, source_assignment=None)


